val Emerald=Color(0xFF0A7A5A);val Navy=Color(0xFF102A43);val Soft=Color(0xFFF3F7F5);val Gold=Color(0xFFE6A817)
class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContent{MaterialTheme(colorScheme=lightColorScheme(primary=Emerald,secondary=Gold,surface=Color.White,background=Soft)){FlowBudgetApp(FinanceStore(this))}}}}
@Composable fun FlowBudgetApp(store:FinanceStore){var tab by remember{mutableIntStateOf(0)};var refresh by remember{mutableIntStateOf(0)};val tx=remember(refresh){store.transactions()};val inc=tx.filter{it.type==TxType.INCOME}.sumOf{it.amount};val exp=tx.filter{it.type==TxType.EXPENSE}.sumOf{it.amount};Scaffold(containerColor=Color.Transparent,bottomBar={NavigationBar(containerColor=Color.White){listOf("Home" to Icons.Default.Home,"Activity" to Icons.Default.ReceiptLong,"Banks" to Icons.Default.AccountBalance,"Plan" to Icons.Default.EventNote,"Plus" to Icons.Default.Star).forEachIndexed{i,p->NavigationBarItem(tab==i,{tab=i},{Icon(p.second,null)},label={Text(p.first)})}}}){pad->Box(Modifier.padding(pad).fillMaxSize()){Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(Color(0xFFF1FAF7),Color(0xFFF7F8FC),Color.White)))){when(tab){0->Dashboard(store,inc,exp,tx);1->Transactions(store,tx){refresh++};2->Banks(store){refresh++};3->FuturePlan(store,tx){refresh++};else->Premium(store,tx){refresh++}}}}}}
fun money(v:Double)=NumberFormat.getCurrencyInstance(Locale("en","NG")).format(v)
@Composable fun Title(t:String,s:String){Column(Modifier.padding(bottom=18.dp)){Text(t,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.ExtraBold,color=Navy);Text(s,color=Color.Gray)}}
@Composable fun Dashboard(store:FinanceStore,inc:Double,exp:Double,tx:List<Transaction>){LazyColumn(Modifier.fillMaxSize().padding(18.dp)){item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Column{Text("Good day",color=Color.Gray);Text("Flow Budget",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,color=Navy)};Surface(shape=RoundedCornerShape(50),color=if(store.premium())Gold else Emerald){Text(if(store.premium())" PLUS " else " BASIC ",Modifier.padding(8.dp),color=Color.White,fontWeight=FontWeight.Bold)}};Spacer(Modifier.height(18.dp));Box(Modifier.fillMaxWidth().background(Brush.linearGradient(listOf(Navy,Emerald)),RoundedCornerShape(26.dp)).padding(24.dp)){Column{Text("TOTAL BALANCE",color=Color.White.copy(.75f));Text(money(inc-exp),style=MaterialTheme.typography.headlineLarge,color=Color.White,fontWeight=FontWeight.ExtraBold);Spacer(Modifier.height(20.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Metric("Income",money(inc),Color.White);Metric("Spent",money(exp),Color.White)}}};Spacer(Modifier.height(20.dp));Text("Monthly plan",fontWeight=FontWeight.Bold,color=Navy);Spacer(Modifier.height(8.dp));ElevatedCard(shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(18.dp)){val b=store.budget();LinearProgressIndicator(progress={if(b<=0)0f else (exp/b).toFloat().coerceIn(0f,1f)},Modifier.fillMaxWidth().height(9.dp));Spacer(Modifier.height(10.dp));Text(money(exp)+" spent of "+money(b));Text(money((b-exp).coerceAtLeast(0.0))+" remaining",color=Emerald,fontWeight=FontWeight.SemiBold)}};Spacer(Modifier.height(22.dp));Text("Recent transactions",fontWeight=FontWeight.Bold,color=Navy)};items(tx.take(6)){TxRow(it)}}}
@Composable fun Metric(a:String,b:String,c:Color){Column{Text(a,color=c.copy(.7f));Text(b,color=c,fontWeight=FontWeight.Bold)}}
@Composable fun TxRow(t:Transaction){Card(Modifier.fillMaxWidth().padding(vertical=5.dp),shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(containerColor=Color.White)){ListItem(colors=ListItemDefaults.colors(containerColor=Color.Transparent),leadingContent={Surface(shape=RoundedCornerShape(12.dp),color=if(t.type==TxType.INCOME)Color(0xFFE5F6EF) else Color(0xFFFFECE8)){Icon(if(t.type==TxType.INCOME)Icons.Default.SouthWest else Icons.Default.NorthEast,null,Modifier.padding(10.dp),tint=if(t.type==TxType.INCOME)Emerald else Color(0xFFC84B31))}},headlineContent={Text(t.category,fontWeight=FontWeight.Bold)},supportingContent={Text(t.bank+" "+t.account+" • "+SmartAnalyzer.label(t.timestamp))},trailingContent={Text((if(t.type==TxType.INCOME)"+ " else "- ")+money(t.amount),fontWeight=FontWeight.Bold,color=if(t.type==TxType.INCOME)Emerald else Navy)})}}
@Composable fun Transactions(store:FinanceStore,tx:List<Transaction>,changed:()->Unit){var show by remember{mutableStateOf(false)};var selected by remember{mutableStateOf("All accounts")};val options=listOf("All accounts")+tx.map{it.bank+" "+it.account}.distinct();if(selected!="All accounts"&&selected !in options)selected="All accounts";val shown=if(selected=="All accounts")tx else tx.filter{it.bank+" "+it.account==selected};Column(Modifier.fillMaxSize().padding(18.dp)){Title("Activity","Transactions by bank and account");FilterMenu("Account",selected,options){selected=it};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){Text(shown.size.toString()+" transactions",color=Color.Gray);Button({show=true},shape=RoundedCornerShape(14.dp)){Icon(Icons.Default.Add,null);Text(" Add")}};Spacer(Modifier.height(8.dp));if(shown.isEmpty())Box(Modifier.fillMaxWidth().padding(28.dp),contentAlignment=Alignment.Center){Text("No transactions for this account.",color=Color.Gray)}else LazyColumn{items(shown){TxRow(it)}}};if(show)AddDialog({show=false}){store.add(it);show=false;changed()}}
@Composable fun AddDialog(close:()->Unit,add:(Transaction)->Unit){var a by remember{mutableStateOf("")};var n by remember{mutableStateOf("")};var inc by remember{mutableStateOf(false)};AlertDialog(onDismissRequest=close,title={Text("Add transaction")},text={Column{OutlinedTextField(a,{a=it},label={Text("Amount")});OutlinedTextField(n,{n=it},label={Text("Description")});Row(verticalAlignment=Alignment.CenterVertically){Switch(inc,{inc=it});Text(if(inc)" Income" else " Expense")}}},confirmButton={Button({a.toDoubleOrNull()?.let{add(Transaction(type=if(inc)TxType.INCOME else TxType.EXPENSE,amount=it,category=if(inc)"Income" else "Other",note=n))}}){Text("Save")}},dismissButton={TextButton(close){Text("Cancel")}})}
@Composable fun Banks(store:FinanceStore,changed:()->Unit){val ctx=LocalContext.current;val scope=rememberCoroutineScope();var discovered by remember{mutableStateOf(emptyList<SmsSender>())};var allowed by remember{mutableStateOf(store.allowedSenders())};var status by remember{mutableStateOf("Grant access, then scan your messages.")};var importing by remember{mutableStateOf(false)};fun scan(){runCatching{discovered=SmsImporter.discover(ctx);status=if(discovered.isEmpty())"No financial SMS senders detected yet." else "Found "+discovered.size+" possible financial senders."}.onFailure{status="SMS access is not available."}};val launcher=rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()){p->if(p[Manifest.permission.READ_SMS]==true)scan()};LaunchedEffect(Unit){if(ContextCompat.checkSelfPermission(ctx,Manifest.permission.READ_SMS)==PackageManager.PERMISSION_GRANTED)scan()};LazyColumn(Modifier.fillMaxSize().padding(18.dp)){item{Title("Bank connections","Secure, private transaction import");GlassCard{Icon(Icons.Default.Security,null,tint=Emerald,modifier=Modifier.size(34.dp));Text("Your SMS stays on this phone",fontWeight=FontWeight.Bold,color=Navy);Text("Approve only the banks you want Flow Budget to analyze.");Spacer(Modifier.height(12.dp));Button({launcher.launch(arrayOf(Manifest.permission.READ_SMS,Manifest.permission.RECEIVE_SMS))},shape=RoundedCornerShape(16.dp)){Text("Grant SMS access")};OutlinedButton({scan()},shape=RoundedCornerShape(16.dp)){Text("Scan existing SMS")};Text(status,color=Color.Gray)};Spacer(Modifier.height(18.dp));Text("Detected senders",fontWeight=FontWeight.Bold,color=Navy)};items(discovered,key={it.address}){s->val isAllowed=s.address.uppercase() in allowed;Card(Modifier.fillMaxWidth().padding(vertical=5.dp).animateContentSize(),shape=RoundedCornerShape(20.dp)){ListItem(headlineContent={Text(s.address,fontWeight=FontWeight.Bold)},supportingContent={Text(s.count.toString()+" financial-looking messages\n"+s.sample)},trailingContent={Switch(isAllowed,{on->if(on)store.addSender(s.address)else store.removeSender(s.address);allowed=store.allowedSenders();changed()})})}};item{if(allowed.isNotEmpty()){Spacer(Modifier.height(14.dp));Button(enabled=!importing,onClick={importing=true;status="Importing transactions…";scope.launch{val n=withContext(Dispatchers.IO){SmsImporter.importAllowed(ctx,store)};status="$n new transactions imported";importing=false;changed()}},modifier=Modifier.fillMaxWidth().height(54.dp),shape=RoundedCornerShape(18.dp)){if(importing){CircularProgressIndicator(Modifier.size(22.dp),strokeWidth=2.dp,color=Color.White);Text("  Importing…")}else{Icon(Icons.Default.Download,null);Text(" Import from "+allowed.size+" approved bank(s)")}};AnimatedVisibility(importing){Text("Reading and organizing your bank alerts. You can stay on this page.",Modifier.padding(10.dp),color=Emerald)}}}}}
@Composable fun Budget(store:FinanceStore,exp:Double,changed:()->Unit){var v by remember{mutableStateOf(store.budget().toLong().toString())};Column(Modifier.padding(18.dp)){Title("Monthly budget","Give every naira a purpose");ElevatedCard(shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(20.dp)){OutlinedTextField(v,{v=it},label={Text("Spending limit (₦)")});Spacer(Modifier.height(10.dp));Button({v.toDoubleOrNull()?.let{store.setBudget(it);changed()}},shape=RoundedCornerShape(14.dp)){Text("Save budget")};Spacer(Modifier.height(20.dp));Text("Spent  "+money(exp));Text("Available  "+money((store.budget()-exp).coerceAtLeast(0.0)),fontWeight=FontWeight.Bold,color=Emerald)}}}}
@Composable fun Premium(store:FinanceStore,tx:List<Transaction>,changed:()->Unit){var premiumActive by remember{mutableStateOf(store.premium())};val p=premiumActive;var bank by remember{mutableStateOf("All accounts")};var period by remember{mutableStateOf("This month")};val cal=java.util.Calendar.getInstance();var month by remember{mutableIntStateOf(cal.get(java.util.Calendar.MONTH))};var year by remember{mutableIntStateOf(cal.get(java.util.Calendar.YEAR))};val accounts=listOf("All accounts")+tx.filter{it.bank!="Manual"}.map{it.bank+" "+it.account}.distinct();val filtered=SmartAnalyzer.filter(tx,bank,period,month,year);val inc=filtered.filter{it.type==TxType.INCOME}.sumOf{it.amount};val exp=filtered.filter{it.type==TxType.EXPENSE}.sumOf{it.amount};LazyColumn(Modifier.fillMaxSize().padding(18.dp)){item{Title(if(p)"Flow Budget Plus ✦" else "Flow Budget Plus","Smart analysis across banks and time");Card(colors=CardDefaults.cardColors(containerColor=if(p)Color(0xFFFFF4D6) else Color.White),shape=RoundedCornerShape(24.dp)){Column(Modifier.padding(22.dp)){Icon(Icons.Default.WorkspacePremium,null,tint=Gold,modifier=Modifier.size(38.dp));Text(if(p)"Premium intelligence is ACTIVE" else "Unlock financial intelligence",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold,color=Navy);Text(if(p)"Filter banks, accounts and periods, then get private spending analysis." else "Premium turns your imported transactions into bank-by-bank insights and budget suggestions.");Spacer(Modifier.height(14.dp));Button({premiumActive=!premiumActive;store.setPremium(premiumActive);changed()},colors=ButtonDefaults.buttonColors(containerColor=if(p)Navy else Gold)){Text(if(p)"Return to Basic" else "Activate Premium test mode")}}};Spacer(Modifier.height(18.dp));if(p){Text("Analyze",fontWeight=FontWeight.Bold,color=Navy);FilterMenu("Account / bank",bank,accounts){bank=it};FilterMenu("Period",period,listOf("This month","Selected month","This year","All time")){period=it};if(period=="Selected month"){Row(Modifier.fillMaxWidth()){FilterMenu("Month",java.text.DateFormatSymbols().months[month],(0..11).map{java.text.DateFormatSymbols().months[it]}){month=java.text.DateFormatSymbols().months.indexOf(it)};Spacer(Modifier.width(8.dp));FilterMenu("Year",year.toString(),(cal.get(java.util.Calendar.YEAR) downTo cal.get(java.util.Calendar.YEAR)-5).map{it.toString()}){year=it.toInt()}}};if(period=="This year"){FilterMenu("Year",year.toString(),(cal.get(java.util.Calendar.YEAR) downTo cal.get(java.util.Calendar.YEAR)-5).map{it.toString()}){year=it.toInt()}};Spacer(Modifier.height(10.dp));Box(Modifier.fillMaxWidth().background(Brush.linearGradient(listOf(Navy,Emerald)),RoundedCornerShape(22.dp)).padding(20.dp)){Column{Text(bank,color=Color.White.copy(.75f));Text("Net "+money(inc-exp),style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,color=Color.White);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Metric("Income",money(inc),Color.White);Metric("Spent",money(exp),Color.White)}}};Spacer(Modifier.height(16.dp));Text("Smart spending insight",fontWeight=FontWeight.Bold,color=Navy);SmartAnalyzer.insights(filtered,store.budget()).forEach{PremiumCard(it.title,it.body,Icons.Default.AutoGraph)};Text("Transactions in this view: "+filtered.size,color=Color.Gray,modifier=Modifier.padding(vertical=8.dp))}else{Text("Premium includes",fontWeight=FontWeight.Bold,color=Navy);Text("Bank/account filters • day/month/year intelligence • smart spending insights • private AI-style analysis • budget suggestions • advanced reports",Modifier.padding(top=10.dp))}}}}
