@Composable fun FuturePlan(store:FinanceStore,tx:List<Transaction>,changed:()->Unit){val ctx=LocalContext.current;var show by remember{mutableStateOf(false)};val plans=store.futureExpenses();val accounts=listOf("All accounts")+tx.map{it.bank+" "+it.account}.distinct();val permission=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){};LaunchedEffect(Unit){FlowNotifications.ensure(ctx);if(android.os.Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(ctx,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)permission.launch(Manifest.permission.POST_NOTIFICATIONS)};LazyColumn(Modifier.fillMaxSize().padding(18.dp)){item{Title("Future spending","Plan ahead and let Flow Budget remind you");Box(Modifier.fillMaxWidth().background(Brush.linearGradient(listOf(Color(0xFF183B56),Emerald)),RoundedCornerShape(28.dp)).padding(22.dp)){Column{Icon(Icons.Default.NotificationsActive,null,tint=Color.White);Text("Stay ahead of upcoming expenses",color=Color.White,fontWeight=FontWeight.Bold,style=MaterialTheme.typography.titleLarge);Text("Add bills, purchases, subscriptions or savings commitments and receive a reminder before they are due.",color=Color.White.copy(.8f));Spacer(Modifier.height(14.dp));Button({show=true},colors=ButtonDefaults.buttonColors(containerColor=Color.White,contentColor=Navy)){Icon(Icons.Default.Add,null);Text(" Plan an expense")}}};Spacer(Modifier.height(18.dp));Text("Upcoming",fontWeight=FontWeight.Bold,color=Navy)};items(plans,key={it.id}){p->ElevatedCard(Modifier.fillMaxWidth().padding(vertical=6.dp),shape=RoundedCornerShape(20.dp)){ListItem(leadingContent={Icon(Icons.Default.Event,null,tint=Emerald)},headlineContent={Text(p.title,fontWeight=FontWeight.Bold)},supportingContent={Text(SmartAnalyzer.label(p.dueAt)+" • "+p.account+(if(p.reminder)" • Reminder on" else ""))},trailingContent={Column(horizontalAlignment=Alignment.End){Text(money(p.amount),fontWeight=FontWeight.Bold);IconButton({store.removeFutu